def transform(grid):
    h, w = len(grid), len(grid[0])

    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    def segments(size, separators):
        out, start = [], 0
        for i in separators:
            if start < i:
                out.append((start, i))
            start = i + 1
        if start < size:
            out.append((start, size))
        return out

    row_segs = segments(h, sep_rows)
    col_segs = segments(w, sep_cols)
    background = max(set(v for row in grid for v in row),
                     key=lambda v: sum(row.count(v) for row in grid))

    result = []
    for r0, r1 in row_segs:
        row_out = []
        for c0, c1 in col_segs:
            count = sum(grid[r][c] != background
                        for r in range(r0, r1)
                        for c in range(c0, c1))
            row_out.append(1 if count >= 2 else background)
        result.append(row_out)
    return result
